<div class="rounded-xl border bg-slate-50 p-4 space-y-3" data-item><div class="flex justify-end"><button type="button" data-remove-item class="text-xs font-bold text-red-600">Remove item</button></div><div class="grid gap-3 sm:grid-cols-2"><div><label class="field">Badge / step number</label><input name="sections[__SECTION__][items][__ITEM__][badge]"></div><div><label class="field">Title / question</label><input name="sections[__SECTION__][items][__ITEM__][title]"></div></div><div><label class="field">Body / answer</label><textarea name="sections[__SECTION__][items][__ITEM__][body]" rows="3"></textarea></div><div class="grid gap-3 sm:grid-cols-2"><div><label class="field">Link label</label><input name="sections[__SECTION__][items][__ITEM__][link_label]"></div><div><label class="field">Link URL</label><input name="sections[__SECTION__][items][__ITEM__][link_url]"></div><div><label class="field">Optional image</label><input type="file" name="sections[__SECTION__][items][__ITEM__][image]" accept="image/jpeg,image/png,image/webp"><input type="hidden" name="sections[__SECTION__][items][__ITEM__][existing_image_path]"></div><div><label class="field">Image alt text</label><input name="sections[__SECTION__][items][__ITEM__][image_alt]"></div></div></div>
